html:
{% set qr_svg = get_token_qr_svg(doc.name) %}
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  @page { size: 80mm 120mm; margin: 0; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', Arial, sans-serif;
    background: #fff;
    color: #1e293b;
    width: 80mm;
    padding: 6mm 6mm 4mm;
  }
  .slip-header {
    text-align: center;
    border-bottom: 1px solid #e2e8f0;
    padding-bottom: 4mm;
    margin-bottom: 4mm;
  }
  .clinic-name {
    font-size: 11pt;
    font-weight: 700;
    letter-spacing: 0.02em;
  }
  .session-date {
    font-size: 7pt;
    color: #64748b;
    margin-top: 1mm;
  }
  .token-block {
    text-align: center;
    margin: 4mm 0;
  }
  .token-label {
    font-size: 7pt;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #64748b;
  }
  .token-value {
    font-size: 32pt;
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.02em;
    color: #0f172a;
  }
  .patient-block {
    border-top: 1px solid #e2e8f0;
    padding-top: 3mm;
    margin-top: 3mm;
  }
  .patient-name {
    font-size: 10pt;
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .meta-row {
    font-size: 7pt;
    color: #475569;
    margin-top: 1.5mm;
  }
  .qr-block {
    text-align: center;
    margin: 4mm 0 2mm;
  }
  .qr-block svg {
    width: 30mm;
    height: 30mm;
  }
  .qr-hint {
    font-size: 6.5pt;
    color: #94a3b8;
    margin-top: 1.5mm;
  }
  .footer-note {
    font-size: 6pt;
    color: #94a3b8;
    text-align: center;
    border-top: 1px dashed #e2e8f0;
    padding-top: 2mm;
    margin-top: 2mm;
  }
</style>
</head>
<body>
<div class="slip-header">
  <div class="clinic-name">Marley Healthcare</div>
  <div class="session-date">{{ frappe.format_date(doc.creation, 'EEE, dd MMM yyyy') }}</div>
</div>

<div class="token-block">
  <div class="token-label">Your Token</div>
  <div class="token-value">{{ doc.token or doc.name }}</div>
</div>

<div class="patient-block">
  <div class="patient-name">{{ doc.patient_name }}</div>
  <div class="meta-row">
    {% if doc.load_class == 'review_load' %}Review{% elif doc.load_class == 'non_review_load' %}New Patient{% endif %}
    {% if doc.channel %} &middot; {{ doc.channel | capitalize }}{% endif %}
    {% if doc.report_by_time %} &middot; Report by {{ frappe.format_datetime(doc.report_by_time, 'hh:mm a') }}{% endif %}
  </div>
</div>

{% if qr_svg %}
<div class="qr-block">
  {{ qr_svg }}
  <div class="qr-hint">Scan at the arrival kiosk when you reach the clinic</div>
</div>
{% endif %}

<div class="footer-note">Keep this slip with you &bull; {{ doc.name }}</div>
</body>
</html>
